module main:
- main: start [main::s, main::r]
- s: mutex_lock main::m; mutex_unlock main::m
- r: mutex_lock main::m; mutex_unlock main::m
- ch1_send: channel_send main::ch1
- ch1_recv: channel_recv main::ch1
- ch2_send: channel_send main::ch2
- ch2_recv: channel_recv main::ch2

