module main:
- main: spawn main::supervisor; join
- supervisor: start [main::w1, main::w2, main::w3]
- w1: semaphore_acquire main::s; semaphore_release main::s
- w2: semaphore_acquire main::s; semaphore_release main::s
- w3: semaphore_acquire main::s; semaphore_release main::s

